import express from 'express';
import { DatabaseSync } from 'node:sqlite';
import { tokenAuth } from '../middleware/auth.js';

const app = express();
const db = new DatabaseSync('./cache/sync_drafts.sqlite');

app.get('/api/sync/drafts/:draftId', tokenAuth, (req, res) => {
  const { draftId } = req.params;

  // Ensure draft belongs strictly to the caller's authorized workspace
  const query = db.prepare(`
    SELECT id, workspace_id, title, markdown_body, author_id, last_synced_at
    FROM synced_drafts
    WHERE id = ? AND workspace_id = ?
  `);

  const draft = query.get(draftId, req.user.workspaceId);
  if (!draft) {
    return res.status(404).json({ error: 'Draft not found or access denied' });
  }

  res.json({ draft });
});

export default app;
